262	fn cache_list_json_output_is_parseable_and_correct() {
263	    let home = TempDir::new().unwrap();
264	    let store = isolated_store(home.path());
265	    store
266	        .store("http:https://example.com", "alpha", "aaa", 3600)
267	        .unwrap();
268	    store
269	        .store("http:https://example.com", "beta", "bbbbb", 3600)
