272	    // Use non-PTY capture so we get clean stdout for JSON parsing.
273	    let (stdout, _stderr, code) =
274	        run_cache_isolated(&["cache", "list", "--json"], home.path());
275	    assert_eq!(code, 0, "cache list --json should exit 0, stdout: {stdout}");
276	
277	    // Locate the JSON array in stdout (ui.message prefixes may add no
278	    // content but trailing newline is fine).
279	    let start = stdout.find('[').expect("JSON array not found in stdout");
280	    let end = stdout.rfind(']').expect("JSON array end not found in stdout");
281	    let json_slice = &stdout[start..=end];
282	    let parsed: serde_json::Value =
283	        serde_json::from_str(json_slice).expect("list --json must emit valid JSON");
284	
285	    let arr = parsed.as_array().expect("JSON root must be an array");
286	    assert_eq!(arr.len(), 2, "expected exactly 2 entries");
287	
288	    // Every entry must carry these documented fields.
289	    for entry in arr {
290	        assert!(entry.get("source_id").is_some(), "missing source_id");
291	        assert!(entry.get("template_name").is_some(), "missing template_name");
292	        assert!(entry.get("metadata").is_some(), "missing metadata block");
293	    }
294	
295	    // Template names must match what we seeded.
296	    let names: Vec<&str> = arr
297	        .iter()
298	        .map(|e| e["template_name"].as_str().unwrap())
299	        .collect();
300	    assert!(names.contains(&"alpha"));
301	    assert!(names.contains(&"beta"));
302	}
