76	fn list_cache(
77	    store: &CacheStore,
78	    verbose: bool,
79	    json: bool,
80	    ui: &mut dyn UserInterface,
81	) -> Result<i32> {
82	    let entries = store.list()?;
83	
84	    if entries.is_empty() {
85	        ui.message("Cache is empty");
86	        return Ok(0);
87	    }
88	
89	    if json {
90	        let output = serde_json::to_string_pretty(&entries)?;
91	        ui.message(&output);
92	        return Ok(0);
93	    }
94	
95	    ui.message(&format!("{} cached entries:\n", entries.len()));
96	
97	    for entry in entries {
98	        let status = if entry.is_expired() {
99	            "expired"
100	        } else {
101	            "fresh"
102	        };
103	        let remaining = entry.metadata.remaining_ttl();
104	        let ttl_str = if remaining > 0 {
105	            format_duration(chrono::Duration::seconds(remaining))
106	        } else {
107	            "expired".to_string()
108	        };
109	
110	        if verbose {
111	            ui.message(&format!("  {} ({})", entry.template_name, entry.source_id));
112	            ui.message(&format!("    Status: {}", status));
113	            ui.message(&format!("    TTL: {}", ttl_str));
114	            ui.message(&format!("    Size: {} bytes", entry.metadata.size_bytes));
115	            if let Some(etag) = &entry.metadata.etag {
116	                ui.message(&format!("    ETag: {}", etag));
117	            }
118	            if let Some(sha) = &entry.metadata.commit_sha {
119	                ui.message(&format!("    Commit: {}", sha));
120	            }
121	            ui.message("");
122	        } else {
123	            ui.message(&format!(
124	                "  {} [{}] {}",
125	                entry.template_name, status, ttl_str
126	            ));
127	        }
128	    }
129	
130	    Ok(0)
131	}
132	
133	fn clear_cache(
134	    store: &CacheStore,
135	    expired_only: bool,
136	    force: bool,
137	    ui: &mut dyn UserInterface,
138	) -> Result<i32> {
139	    if expired_only {
140	        let validator = CacheValidator::new(store);
141	        let removed = validator.cleanup_expired()?;
142	        ui.success(&format!("Cleared {} expired entries", removed));
143	        return Ok(0);
144	    }
145	
146	    let entries = store.list()?;
147	    if entries.is_empty() {
148	        ui.message("Cache is already empty");
149	        return Ok(0);
150	    }
151	
152	    let count = entries.len();
153	    if !force && ui.is_interactive() {
154	        let prompt = Prompt {
155	            key: "clear_cache".to_string(),
156	            question: format!("Clear {} cached entries?", count),
157	            prompt_type: PromptType::Confirm,
158	            default: Some("false".to_string()),
159	        };
160	
161	        match ui.prompt(&prompt)? {
162	            PromptResult::Bool(true) => {}
163	            _ => {
164	                ui.message("Cancelled");
165	                return Ok(0);
166	            }
167	        }
168	    }
169	
170	    let cleared = store.clear()?;
171	    ui.success(&format!("Cleared {} entries", cleared));
172	
173	    Ok(0)
174	}
175	
176	/// Only requires `OutputWriter` — displays statistics but does not prompt.
177	fn show_stats(store: &CacheStore, ui: &mut dyn OutputWriter) -> Result<i32> {
178	    let entries = store.list()?;
179	    let total_size = store.total_size()?;
180	    let expired_count = entries.iter().filter(|e| e.is_expired()).count();
181	    let fresh_count = entries.len() - expired_count;
182	
183	    ui.message("Cache Statistics:\n");
184	    ui.message(&format!("  Total entries: {}", entries.len()));
185	    ui.message(&format!("  Fresh: {}", fresh_count));
186	    ui.message(&format!("  Expired: {}", expired_count));
187	    ui.message(&format!("  Total size: {} bytes", total_size));
188	    ui.message(&format!("  Location: {}", store.root().display()));
189	
190	    Ok(0)
191	}
