17	/// Loads templates from remote sources with caching.
18	#[derive(Debug, Clone)]
19	pub struct RemoteLoader {
20	    /// Fetched and parsed templates, keyed by `category/name`.
21	    templates: HashMap<String, (Template, u32)>,
22	}
23	
24	impl RemoteLoader {
25	    /// Create a new remote loader by fetching templates from the given sources.
26	    ///
27	    /// HTTP sources are fetched into the shared `CacheStore`; Git sources are
28	    /// cloned (or updated) into `git_fetcher`'s clone directory and their
29	    /// templates directory is walked for `*.yml`/`*.yaml` files.
30	    pub fn new(
31	        sources: &[TemplateSourceConfig],
32	        http_fetcher: &HttpFetcher,
33	        git_fetcher: &GitFetcher,
34	        cache: &CacheStore,
35	    ) -> Result<Self> {
36	        let mut templates = HashMap::new();
37	
38	        // Visit sources in priority order (lower `priority` number wins on
39	        // collision). Stable sort preserves declaration order among ties so
40	        // the user's listed-first source breaks the tie.
41	        let mut ordered: Vec<&TemplateSourceConfig> = sources.iter().collect();
42	        ordered.sort_by_key(|s| s.priority);
43	
44	        for source in ordered {
45	            let result = match source.effective_kind() {
46	                TemplateSourceKind::Http => Self::load_http_source(source, http_fetcher, cache),
47	                TemplateSourceKind::Git => Self::load_git_source(source, git_fetcher),
48	            };
49	
50	            match result {
51	                Ok(loaded) => {
52	                    for template in loaded {
53	                        // Higher-priority sources (lower number) win on collision.
54	                        let key = format!("{}/{}", template.category, template.name);
55	                        templates.entry(key).or_insert((template, source.priority));
56	                    }
57	                }
58	                Err(e) => {
59	                    tracing::warn!("Failed to load templates from {}: {}", source.url, e);
60	                }
61	            }
62	        }
63	
64	        Ok(Self { templates })
65	    }
66	
67	    /// Create an empty remote loader (no sources).
68	    pub fn empty() -> Self {
69	        Self {
70	            templates: HashMap::new(),
71	        }
72	    }
73	
74	    /// Load templates from a single HTTP source.
75	    fn load_http_source(
76	        source: &TemplateSourceConfig,
77	        fetcher: &HttpFetcher,
78	        cache: &CacheStore,
79	    ) -> Result<Vec<Template>> {
80	        let source_id = format!("http:{}", source.url);
81	
82	        // Check cache first
83	        if let Some(entry) = cache.load(&source_id, "_index")? {
84	            if !entry.is_expired() {
85	                let content = cache.read_content(&entry)?;
86	                return Self::parse_templates(&content);
87	            }
88	        }
89	
90	        // Fetch from remote
91	        let response = fetcher
92	            .fetch(&source.url)
93	            .with_context(|| format!("Failed to fetch template source: {}", source.url))?;
94	
95	        // Cache the response
96	        let ttl_seconds = source
97	            .cache
98	            .as_ref()
99	            .and_then(|c| parse_ttl(&c.ttl).ok())
100	            .map(|d| d.num_seconds() as u64)
101	            .unwrap_or(604800);
102	        cache.store(&source_id, "_index", &response.content, ttl_seconds)?;
103	
104	        Self::parse_templates(&response.content)
105	    }
