        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "good", "content", 3600)
            .unwrap();
        store
            .store("http:test", "will_corrupt", "content", 3600)
            .unwrap();

        let meta_path = store.metadata_path("http:test", "will_corrupt");
        fs::write(&meta_path, "corrupted!!!").unwrap();

        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].template_name, "good");
    }

    #[test]
    fn concurrent_stores_produce_consistent_state() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = root.clone();
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    let content = format!("content from thread {}", i);
                    store
                        .store("http:test", "shared-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let store = CacheStore::new(temp.path());
        let entry = store
            .load("http:test", "shared-template")
            .unwrap()
            .expect("Entry should exist after concurrent stores");

        let content = store.read_content(&entry).unwrap();
        assert!(
            content.starts_with("content from thread "),
            "Content should be a complete write from one thread, got: {:?}",
            content
        );

        let no_tmp_files: Vec<_> = fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .filter(|e| {
                e.path()
                    .extension()
                    .is_some_and(|ext| ext == "tmp")
            })
            .collect();
        assert!(
            no_tmp_files.is_empty(),
            "No temp files should remain after concurrent stores"
        );
    }
}

