            .store("http:test", "template1", "content", 3600)
            .unwrap();

        let meta_path = store.metadata_path("http:test", "template1");
        fs::write(&meta_path, "not valid json{{{").unwrap();

        let result = store.load("http:test", "template1").unwrap();
        assert!(result.is_none(), "Corrupted metadata should return None");
    }

    #[test]
    fn load_returns_none_for_truncated_metadata() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        let meta_path = store.metadata_path("http:test", "template1");
        fs::write(&meta_path, "{\"source_id\":").unwrap();

        let result = store.load("http:test", "template1").unwrap();
        assert!(result.is_none(), "Truncated metadata should return None");
    }

    #[test]
    fn list_skips_corrupted_entries() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "good", "content", 3600)
            .unwrap();
        store
            .store("http:test", "will_corrupt", "content", 3600)
